-- +goose Up
--
-- A1 squashed init (2026-10-18). Authority: owner-decisions A–M, N1–N8;
-- apps/api/docs/design/graphql-product/migrations.md target inventory.
-- Pointcrawl-only maps (C3). Inbox notifications (D1/N4). No legacy 0003 upgrade path.
--
-- Dual-key convention (API layer):
--   * Internal PK `id` is BIGINT GENERATED BY DEFAULT AS IDENTITY — used for all FKs.
--   * Public `public_id` is UUID NOT NULL UNIQUE DEFAULT gen_random_uuid() for addressable rows.
--
CREATE EXTENSION IF NOT EXISTS "pgcrypto";

CREATE TABLE agent_questions (
    id bigint NOT NULL,
    public_id uuid DEFAULT gen_random_uuid() NOT NULL,
    job_id bigint NOT NULL,
    question text NOT NULL,
    history jsonb,
    result jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE archon_assignments (
    member_id bigint NOT NULL,
    region_id bigint NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    granted_by bigint
);

CREATE TABLE background_jobs (
    id bigint NOT NULL,
    public_id uuid DEFAULT gen_random_uuid() NOT NULL,
    job_key text NOT NULL,
    kind text NOT NULL,
    lane text DEFAULT 'default'::text NOT NULL,
    state text DEFAULT 'queued'::text NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    error_message text,
    lease_token bigint DEFAULT 0 NOT NULL,
    lease_expires_at timestamp with time zone,
    claimed_at timestamp with time zone,
    attempt_deadline_at timestamp with time zone,
    question_deadline_at timestamp with time zone,
    completion_operation text,
    completion_payload jsonb,
    next_run_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    redrive_count integer DEFAULT 0 NOT NULL,
    safe_error_code text,
    CONSTRAINT agent_question_deadline CHECK (((kind = 'agent_question'::text) = (question_deadline_at IS NOT NULL))),
    CONSTRAINT background_jobs_lease_token_check CHECK ((lease_token >= 0)),
    CONSTRAINT background_jobs_state_check CHECK ((state = ANY (ARRAY['queued'::text, 'running'::text, 'succeeded'::text, 'retry_wait'::text, 'repair_required'::text, 'dead'::text, 'cancelled'::text]))),
    CONSTRAINT job_completion_pair CHECK (((completion_operation IS NULL) = (completion_payload IS NULL))),
    CONSTRAINT job_lease_state CHECK ((((state = 'running'::text) AND (lease_expires_at IS NOT NULL) AND (claimed_at IS NOT NULL) AND (attempt_deadline_at IS NOT NULL)) OR ((state <> 'running'::text) AND (lease_expires_at IS NULL) AND (claimed_at IS NULL) AND (attempt_deadline_at IS NULL))))
);

CREATE TABLE backstories (
    id bigint NOT NULL,
    public_id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    lore text DEFAULT ''::text NOT NULL,
    cohort text DEFAULT ''::text NOT NULL,
    source_region_id bigint,
    retired boolean DEFAULT false NOT NULL
);

CREATE TABLE bot_heartbeats (
    id bigint NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    received_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE character_catalog_picks (
    catalog_id bigint NOT NULL,
    character_id bigint NOT NULL
);

CREATE TABLE character_ddb_mirrors (
    character_id bigint NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    synced_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE character_logs (
    id bigint NOT NULL,
    public_id uuid DEFAULT gen_random_uuid() NOT NULL,
    character_id bigint NOT NULL,
    quest_id bigint,
    body text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by bigint
);

CREATE TABLE character_progression_ledger (
    id bigint NOT NULL,
    public_id uuid DEFAULT gen_random_uuid() NOT NULL,
    character_id bigint NOT NULL,
    delta integer NOT NULL,
    reason text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    kind text DEFAULT 'pcxp'::text NOT NULL,
    metadata jsonb,
    note text,
    quest_id bigint,
    recorded_by bigint
);

CREATE TABLE characters (
    id bigint NOT NULL,
    public_id uuid DEFAULT gen_random_uuid() NOT NULL,
    short_code text NOT NULL,
    name text NOT NULL,
    owner_id bigint NOT NULL,
    status text DEFAULT 'pending_approval'::text NOT NULL,
    backstory_id bigint,
    guild_document_id bigint,
    region_id bigint,
    verification_submitted_at timestamp with time zone,
    player_xp integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    background_text text,
    ddb_url text,
    deleted_at timestamp with time zone,
    deleted_by bigint,
    description text,
    CONSTRAINT characters_player_xp_nonneg CHECK ((player_xp >= 0)),
    CONSTRAINT characters_status_check CHECK ((status = ANY (ARRAY['active'::text, 'retired'::text, 'dead'::text, 'pending_approval'::text])))
);

CREATE TABLE creation_catalog (
    id bigint NOT NULL,
    public_id uuid DEFAULT gen_random_uuid() NOT NULL,
    kind text NOT NULL,
    code text NOT NULL,
    name text NOT NULL,
    available boolean DEFAULT true NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    description text,
    introduced_by_region_id bigint,
    retired boolean DEFAULT false NOT NULL,
    CONSTRAINT creation_catalog_kind_check CHECK ((kind = ANY (ARRAY['species'::text, 'class'::text, 'background'::text])))
);

CREATE TABLE discord_activity_events (
    event_id text NOT NULL,
    kind text NOT NULL,
    discord_user_id text NOT NULL,
    channel_id text NOT NULL,
    occurred_at timestamp with time zone NOT NULL,
    amount double precision DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE dm_profiles (
    member_id bigint NOT NULL,
    tagline text,
    philosophy text,
    house_rules text,
    table_info jsonb,
    accepting_players boolean DEFAULT false NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    review_revision integer DEFAULT 0 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT dm_profiles_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'pending'::text, 'approved'::text, 'rejected'::text])))
);

CREATE TABLE document_links (
    source_id bigint NOT NULL,
    document_target_id bigint,
    relation text DEFAULT 'link'::text NOT NULL,
    quest_target_id bigint,
    character_target_id bigint,
    region_target_id bigint,
    target_type text GENERATED ALWAYS AS (
CASE
    WHEN (document_target_id IS NOT NULL) THEN 'document'::text
    WHEN (quest_target_id IS NOT NULL) THEN 'quest'::text
    WHEN (character_target_id IS NOT NULL) THEN 'character'::text
    ELSE 'region'::text
END) STORED NOT NULL,
    target_id bigint GENERATED ALWAYS AS (COALESCE(document_target_id, quest_target_id, character_target_id, region_target_id)) STORED NOT NULL,
    summary_append_order bigint NOT NULL,
    CONSTRAINT document_links_exactly_one_target CHECK ((num_nonnulls(document_target_id, quest_target_id, character_target_id, region_target_id) = 1))
);

CREATE TABLE document_readers (
    document_id bigint NOT NULL,
    member_id bigint NOT NULL
);

CREATE TABLE document_revisions (
    id bigint NOT NULL,
    public_id uuid DEFAULT gen_random_uuid() NOT NULL,
    document_id bigint NOT NULL,
    reason text NOT NULL,
    title text NOT NULL,
    body text NOT NULL,
    frontmatter_yaml text,
    created_by bigint,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    new_value jsonb,
    old_value jsonb,
    policy jsonb,
    published_at timestamp with time zone,
    published_by bigint,
    rev integer NOT NULL,
    visibility text
);

CREATE TABLE documents (
    id bigint NOT NULL,
    public_id uuid DEFAULT gen_random_uuid() NOT NULL,
    kind text NOT NULL,
    slug text NOT NULL,
    title text NOT NULL,
    category text,
    status text DEFAULT 'draft'::text NOT NULL,
    visibility text DEFAULT 'public'::text NOT NULL,
    policy jsonb,
    body text DEFAULT ''::text NOT NULL,
    frontmatter_yaml text,
    author_id bigint,
    published_at timestamp with time zone,
    deleted_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_by bigint,
    published_by bigint,
    version integer DEFAULT 0 NOT NULL,
    CONSTRAINT documents_kind_check CHECK ((kind = ANY (ARRAY['codex_entry'::text, 'rule'::text, 'summary'::text, 'quest_brief'::text, 'community'::text]))),
    CONSTRAINT documents_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'published'::text]))),
    CONSTRAINT documents_visibility_check CHECK ((visibility = ANY (ARRAY['public'::text, 'dm_only'::text, 'restricted'::text])))
);

CREATE TABLE downtime_projects (
    id bigint NOT NULL,
    public_id uuid DEFAULT gen_random_uuid() NOT NULL,
    character_id bigint NOT NULL,
    name text NOT NULL,
    target integer,
    goal text,
    notes text,
    progress integer DEFAULT 0 NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT downtime_projects_status_check CHECK ((status = ANY (ARRAY['active'::text, 'completed'::text, 'abandoned'::text])))
);

CREATE TABLE game_calendar (
    id smallint DEFAULT 1 NOT NULL,
    definition jsonb DEFAULT '{}'::jsonb NOT NULL,
    updated_at timestamp with time zone,
    CONSTRAINT game_calendar_id_check CHECK ((id = 1))
);

CREATE TABLE game_time_map (
    real_date date NOT NULL,
    game_day integer NOT NULL
);

CREATE TABLE idempotency_keys (
    endpoint text NOT NULL,
    key text NOT NULL,
    actor_id bigint NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    fingerprint text,
    receipt jsonb
);

CREATE TABLE lieutenant_assignments (
    member_id bigint NOT NULL,
    npc_document_id bigint NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    granted_by bigint
);

CREATE TABLE maps (
    id bigint NOT NULL,
    public_id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    atlas_code text NOT NULL,
    map_kind text NOT NULL,
    region_id bigint,
    asset_path text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by bigint,
    family text DEFAULT 'campaign'::text NOT NULL,
    CONSTRAINT maps_family_check CHECK ((family ~ '^[A-Za-z0-9][A-Za-z0-9_-]{0,63}$'::text)),
    CONSTRAINT maps_map_kind_check CHECK ((map_kind = 'pointcrawl'::text))
);

CREATE TABLE member_availability (
    id bigint NOT NULL,
    public_id uuid DEFAULT gen_random_uuid() NOT NULL,
    member_id bigint NOT NULL,
    weekday smallint NOT NULL,
    start_minute smallint NOT NULL,
    end_minute smallint NOT NULL,
    note text,
    CONSTRAINT member_availability_end_minute_check CHECK (((end_minute >= 0) AND (end_minute <= 1440))),
    CONSTRAINT member_availability_start_minute_check CHECK (((start_minute >= 0) AND (start_minute <= 1440))),
    CONSTRAINT member_availability_weekday_check CHECK (((weekday >= 0) AND (weekday <= 6))),
    CONSTRAINT member_availability_window_check CHECK ((start_minute < end_minute))
);

CREATE TABLE member_settings (
    member_id bigint NOT NULL,
    timezone text,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    colorblind_safe boolean DEFAULT false NOT NULL,
    density text DEFAULT 'comfortable'::text NOT NULL,
    effects_enabled boolean DEFAULT true NOT NULL,
    mode text DEFAULT 'system'::text NOT NULL,
    notify_character_verification boolean DEFAULT true NOT NULL,
    notify_dm_mentioned boolean DEFAULT true NOT NULL,
    notify_dm_request_decided boolean DEFAULT true NOT NULL,
    notify_document_activity boolean DEFAULT true NOT NULL,
    notify_quest_scheduled boolean DEFAULT true NOT NULL,
    notify_quest_signup boolean DEFAULT true NOT NULL,
    reduced_motion boolean DEFAULT false NOT NULL,
    theme text DEFAULT 'parchment'::text NOT NULL,
    CONSTRAINT member_settings_density_check CHECK ((density = ANY (ARRAY['comfortable'::text, 'compact'::text]))),
    CONSTRAINT member_settings_mode_check CHECK ((mode = ANY (ARRAY['light'::text, 'dark'::text, 'system'::text]))),
    CONSTRAINT member_settings_theme_check CHECK ((theme = ANY (ARRAY['parchment'::text, 'midnight'::text, 'ember'::text, 'dracula'::text, 'vegan'::text])))
);

CREATE TABLE member_unlocks (
    member_id bigint NOT NULL,
    unlockable_id bigint NOT NULL,
    source text NOT NULL,
    granted_by bigint,
    granted_at timestamp with time zone DEFAULT now() NOT NULL,
    note text,
    CONSTRAINT member_unlocks_source_check CHECK ((source = ANY (ARRAY['milestone'::text, 'event'::text, 'cohort'::text, 'grant'::text, 'purchase'::text])))
);

CREATE TABLE members (
    id bigint NOT NULL,
    public_id uuid DEFAULT gen_random_uuid() NOT NULL,
    discord_id text NOT NULL,
    handle text NOT NULL,
    display_name text NOT NULL,
    avatar_url text,
    roles text[] DEFAULT '{player}'::text[] NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    joined_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT members_roles_nonempty CHECK ((cardinality(roles) >= 1)),
    CONSTRAINT members_roles_vocab CHECK ((roles <@ ARRAY['player'::text, 'dm'::text, 'archon'::text, 'lieutenant'::text, 'verifier'::text, 'admin'::text])),
    CONSTRAINT members_status_check CHECK ((status = ANY (ARRAY['active'::text, 'inactive'::text, 'banned'::text])))
);

CREATE TABLE notifications (
    id bigint NOT NULL,
    public_id uuid DEFAULT gen_random_uuid() NOT NULL,
    member_id bigint NOT NULL,
    kind text NOT NULL,
    subject_type text,
    subject_id bigint,
    body text DEFAULT ''::text NOT NULL,
    read_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE pointcrawl_edges (
    directed boolean NOT NULL,
    document_id bigint,
    id bigint NOT NULL,
    kind text NOT NULL,
    label text,
    map_id bigint NOT NULL,
    node_a bigint NOT NULL,
    node_b bigint NOT NULL,
    public_id uuid DEFAULT gen_random_uuid() NOT NULL,
    CONSTRAINT pointcrawl_edges_check CHECK ((node_a <> node_b))
);

CREATE TABLE pointcrawl_entry_links (
    created_at timestamp with time zone NOT NULL,
    created_by bigint NOT NULL,
    document_id bigint NOT NULL,
    map_id bigint NOT NULL,
    node_id bigint NOT NULL,
    relation text NOT NULL,
    CONSTRAINT pointcrawl_entry_links_relation_check CHECK ((relation = ANY (ARRAY['location'::text, 'subject'::text])))
);

CREATE TABLE pointcrawl_nodes (
    created_at timestamp with time zone NOT NULL,
    id bigint NOT NULL,
    map_id bigint NOT NULL,
    name text NOT NULL,
    public_id uuid DEFAULT gen_random_uuid() NOT NULL,
    submap_id bigint,
    x double precision NOT NULL,
    y double precision NOT NULL
);

CREATE TABLE quest_arcs (
    id bigint NOT NULL,
    public_id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    created_by bigint NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE quest_participants (
    quest_id bigint NOT NULL,
    member_id bigint NOT NULL,
    character_id bigint NOT NULL,
    status text DEFAULT 'signed_up'::text NOT NULL,
    manual boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT quest_participants_status_check CHECK ((status = ANY (ARRAY['signed_up'::text, 'waitlisted'::text, 'withdrawn'::text, 'played'::text, 'no_show'::text])))
);

CREATE TABLE quest_pointcrawl_nodes (
    quest_id bigint NOT NULL,
    node_id bigint NOT NULL,
    role text NOT NULL,
    CONSTRAINT quest_pointcrawl_nodes_role_check CHECK ((role = ANY (ARRAY['expected'::text, 'visited'::text])))
);

CREATE TABLE quest_regions (
    quest_id bigint NOT NULL,
    region_id bigint NOT NULL
);

CREATE TABLE quests (
    id bigint NOT NULL,
    public_id uuid DEFAULT gen_random_uuid() NOT NULL,
    short_code text NOT NULL,
    kinds text[] NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    dm_id bigint NOT NULL,
    arc_id bigint,
    scheduled_at timestamp with time zone NOT NULL,
    duration_hours double precision DEFAULT 4 NOT NULL,
    slots_max integer DEFAULT 5 NOT NULL,
    filled_count integer DEFAULT 0 NOT NULL,
    document_id bigint NOT NULL,
    tags text[] DEFAULT '{}'::text[] NOT NULL,
    genres text[] DEFAULT '{}'::text[] NOT NULL,
    avg_party_level integer,
    signup_type text,
    discord_desired_revision integer DEFAULT 0 NOT NULL,
    discord_applied_revision integer DEFAULT 0 NOT NULL,
    discord_message_id text,
    discord_event_id text,
    event_url text,
    created_by bigint NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    closed_at timestamp with time zone,
    deleted_at timestamp with time zone,
    deleted_by bigint,
    CONSTRAINT quests_duration_hours_check CHECK ((duration_hours > (0)::double precision)),
    CONSTRAINT quests_filled_count_check CHECK (((filled_count >= 0) AND (filled_count <= slots_max))),
    CONSTRAINT quests_kinds_nonempty CHECK ((cardinality(kinds) >= 1)),
    CONSTRAINT quests_kinds_vocab CHECK ((kinds <@ ARRAY['standard'::text, 'event'::text, 'lieutenant'::text, 'hexcrawl'::text, 'one_shot'::text, 'mini_campaign'::text])),
    CONSTRAINT quests_signup_type_check CHECK (((signup_type IS NULL) OR (signup_type = ANY (ARRAY['open'::text, 'application'::text, 'invite'::text])))),
    CONSTRAINT quests_slots_max_check CHECK (((slots_max > 0) AND (slots_max <= 100))),
    CONSTRAINT quests_status_check CHECK ((status = ANY (ARRAY['open'::text, 'full'::text, 'played'::text, 'closed'::text, 'cancelled'::text])))
);

CREATE TABLE regions (
    id bigint NOT NULL,
    public_id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    kind text NOT NULL,
    charter_deadline timestamp with time zone,
    document_id bigint,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    deleted_by bigint,
    CONSTRAINT regions_kind_check CHECK ((kind = ANY (ARRAY['server'::text, 'archon'::text, 'uncharted'::text])))
);

CREATE TABLE site_settings (
    key text NOT NULL,
    document_id bigint,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
