CREATE TABLE time_anchors (
    id bigint NOT NULL,
    public_id uuid DEFAULT gen_random_uuid() NOT NULL,
    real_utc timestamp with time zone NOT NULL,
    epoch_day integer NOT NULL,
    rate double precision DEFAULT 1 NOT NULL,
    note text
