CREATE TABLE unlockables (
    id bigint NOT NULL,
    public_id uuid DEFAULT gen_random_uuid() NOT NULL,
    code text NOT NULL,
    active boolean DEFAULT true NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    description text,
    kind text NOT NULL,
    name text NOT NULL,
    unlock_rule jsonb,
    CONSTRAINT unlockables_kind_check CHECK ((kind = ANY (ARRAY['achievement'::text, 'dm_tier'::text]))),
    CONSTRAINT unlockables_unlock_rule_check CHECK (((unlock_rule IS NULL) OR (unlock_rule = '{"type": "admin_grant"}'::jsonb)))
);

CREATE TABLE verifications (
    id bigint NOT NULL,
    public_id uuid DEFAULT gen_random_uuid() NOT NULL,
    subject_type text NOT NULL,
    subject_id bigint NOT NULL,
    verdict text NOT NULL,
    decided_by bigint NOT NULL,
    note text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    review_revision integer,
    CONSTRAINT verifications_verdict_check CHECK ((verdict = ANY (ARRAY['approved'::text, 'rejected'::text])))
);

